function makeIcon({ role, viewBox, paths, outlines = [], fillRule }: Glyph) {
  return function BrandIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        stroke="currentColor"
        fill="currentColor"
        fillRule={fillRule}
        strokeWidth="0"
        role={role}
        viewBox={viewBox}
        height="1em"
        width="1em"
        {...props}
      >
        {paths.map((d, i) => (
          <path key={i} d={d} />
        ))}
        {outlines.map((o, i) => (
          <path key={`o${i}`} d={o.d} fill="none" strokeWidth={o.width} />
        ))}
      </svg>
    )
  }
}

